input_grid = task_data[0]["input"]
expected_output = task_data[0]["output"]

def transform(g):
    """Transform a hollow box of 5s into nested alternating shells of 5 and 2."""
    rows = len(g)
    cols = len(g[0])
    center_r = rows // 2
    center_c = cols // 2
    result = [[0]*cols for _ in range(rows)]

    # Find the outer boundary of the box
    min_r, max_r = None, None
    min_c, max_c = None, None

    for r in range(rows):
        for c in range(cols):
            if g[r][c] == 5:
                if min_r is None or r < min_r: min_r = r
                if max_r is None or r > max_r: max_r = r
                if min_c is None or c < min_c: min_c = c
                if max_c is None or c > max_c: max_c = c

    # For each cell inside the box, calculate its shell
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if g[r][c] != 0:
                dr = abs(r - center_r)
                dc = abs(c - center_c)
                shell = max(dr, dc)

                # Shell 0 is center
                # Pattern: shell 0 = 0 (empty), shell 1 = 5, shell 2 = 2, shell 3 = 5, shell 4 = 2, shell 5 = 5
                if shell == 0:
                    result[r][c] = 0
                elif shell % 2 == 1:
                    result[r][c] = 5
                else:
                    result[r][c] = 2

    return result

